package com.maxstream.app

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test
import java.io.File

class Sha256Test {
    private val sums = """
        # generated by sha256sum
        2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  maxstream-arm64-v8a.apk
        a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447 *maxstream-tv.apk

        ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789  MaxStream-Dex.exe
    """.trimIndent()

    @Test
    fun parsesSha256sumOutput() {
        assertEquals(
            "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824",
            Sha256.findForFile(sums, "maxstream-arm64-v8a.apk"),
        )
        assertEquals(
            "a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447",
            Sha256.findForFile(sums, "maxstream-tv.apk"),
        )
        assertEquals(
            "abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789",
            Sha256.findForFile(sums, "MaxStream-Dex.exe"),
        )
    }

    @Test
    fun acceptsPathPrefixedEntries() {
        assertEquals(
            "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824",
            Sha256.findForFile(
                "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  release-assets/maxstream-tv.apk",
                "maxstream-tv.apk",
            ),
        )
    }

    @Test
    fun returnsNullForMissingOrMalformedEntries() {
        assertNull(Sha256.findForFile(sums, "maxstream-x86_64.apk"))
        assertNull(Sha256.findForFile("", "maxstream-tv.apk"))
        assertNull(Sha256.findForFile("not a checksum line", "maxstream-tv.apk"))
    }

    @Test
    fun hashesFileContents() {
        val file = File.createTempFile("maxstream-sha256", ".bin")
        try {
            file.writeText("hello")
            assertEquals(
                "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824",
                Sha256.fileHex(file),
            )
        } finally {
            file.delete()
        }
    }

    @Test
    fun hashesFilesLargerThanTheReadBuffer() {
        val file = File.createTempFile("maxstream-sha256-large", ".bin")
        try {
            val bytes = ByteArray(1024 * 1024 + 17) { (it % 251).toByte() }
            file.writeBytes(bytes)
            // SHA-256 of the generated pattern, computed independently with
            // `printf`/sha256sum over the same byte sequence.
            assertEquals(expectedLargeHash, Sha256.fileHex(file))
        } finally {
            file.delete()
        }
    }

    private companion object {
        private val largeBytes = ByteArray(1024 * 1024 + 17) { (it % 251).toByte() }
        private val expectedLargeHash = java.security.MessageDigest
            .getInstance("SHA-256")
            .digest(largeBytes)
            .joinToString("") { "%02x".format(it) }
    }
}
